"""Cuaderno del estudiante, 8.º básico Lengua y Literatura, OA 17 (oraciones complejas, referente y coherencia temporal).

Textos originales y breves; cada ejercicio trae el texto que necesita.
Aquí se definen también los ayudantes `L`, `E`, `task`, `MAT` que reutilizan los otros módulos le8_c*.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA17 = "LE08 OA 17"
E = ex


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


MAT = "Este cuaderno, lápiz y los textos escritos en cada ejercicio. Si quieres, lápices de dos colores para subrayar."

# ------------------------------------------------------------------ OA 17
L(OA17, 1,
  MAT,
  "Aprenderé a reconocer cuántas proposiciones tiene una oración compleja y qué relación las une (suma, oposición, causa, consecuencia, condición, concesión, finalidad), para escribir oraciones largas que se entiendan.",
  ["Reconozco el verbo conjugado de una oración.", "Sé qué es un conector."],
  ["Una proposición es un grupo de palabras con un verbo conjugado propio. Una oración compleja tiene dos o más proposiciones. Para contarlas, busca los verbos conjugados: en «Mariana abrió la ventana y respiró aire fresco» hay dos verbos (abrió, respiró), por lo tanto, dos proposiciones.",
   "Las proposiciones se unen de tres maneras. En la yuxtaposición se separan solo con coma o punto y coma («Llegué, saludé, me senté»). En la coordinación se unen con y, o, pero, ni, y ninguna depende de la otra. En la subordinación una proposición depende de otra y la introducen palabras como porque, aunque, si, cuando, para que o que.",
   "Cada conector crea una relación distinta: y suma; pero opone; porque indica causa; así que o por eso indican consecuencia; si indica condición; aunque indica concesión (algo ocurre a pesar de un obstáculo); para que indica finalidad; cuando indica tiempo. Elegir el conector equivocado cambia el sentido de la oración."],
  [("proposición", "grupo de palabras con un verbo conjugado propio"), ("coordinación", "unión de proposiciones que no dependen una de otra"), ("subordinación", "unión en que una proposición depende de otra"), ("yuxtaposición", "unión de proposiciones solo con signos, sin conector"), ("concesión", "relación en que algo ocurre a pesar de un obstáculo")],
  [("Contar proposiciones", "¿Cuántas proposiciones tiene «Cuando sonó el timbre, Ema guardó su cuaderno y salió al patio»?",
    ["Busco los verbos conjugados: sonó, guardó, salió.", "Cada verbo conjugado marca una proposición.", "Cuento tres."],
    "3 proposiciones"),
   ("Elegir la relación", "¿Qué relación marca «aunque» en «Aunque hacía frío, Lucas salió sin chaqueta»?",
    ["Veo las dos ideas: hacía frío (obstáculo) y salió sin chaqueta.", "Lucas salió a pesar del frío.", "Eso es una concesión, no una causa."],
    "Concesión: sale a pesar del frío")],
  [("Creer que «aunque» indica causa.", "Se confunde lo que ocurre «a pesar de» algo con lo que ocurre «a causa de» algo.", "Pregúntate: ¿la primera idea impulsa o estorba la segunda? Si estorba y aun así ocurre, es concesión."),
   ("Pensar que una oración larga siempre es compleja.", "Se cuentan palabras en lugar de verbos conjugados.", "Cuenta los verbos conjugados: con un solo verbo conjugado hay una sola proposición.")],
  ([E("¿Cuántos verbos conjugados tiene «Bruno dibujó un mapa y lo pintó de verde»?", "2", "Son dibujó y pintó, así que hay dos proposiciones."),
    E("En «Llevé paraguas porque el cielo estaba nublado», ¿qué conector une las proposiciones?", "porque", "Es la palabra que introduce la segunda proposición y explica la primera."),
    E("¿Qué relación marca «pero»: oposición o causa?", "Oposición", "«Pero» contrasta dos ideas, no explica el porqué.")],
   [E("«Estudió mucho, así que aprobó la prueba.» ¿La segunda proposición es causa o consecuencia de la primera?", "Consecuencia", "Aprobar es lo que resulta de estudiar mucho."),
    E("En «Aunque llovía, salimos a trotar», ¿salir a trotar ocurre a pesar de la lluvia o a causa de ella?", "A pesar de la lluvia", "«Aunque» presenta un obstáculo que no impide la acción."),
    E("En «Si guardas la masa en el refrigerador, durará más días», ¿qué relación expresa «si»?", "Condición", "La segunda idea ocurre solo bajo la condición de la primera.")],
   [E("Completa con el conector que marca causa: «No fuimos a la plaza ___ hacía mucho frío». Opciones: porque, aunque, para que.", "porque", "Explica la razón de no ir; «aunque» y «para que» cambian la relación."),
    E("Completa con un conector de finalidad: «Ahorro dinero ___ comprar una bicicleta». Opciones: para, porque, pero.", "para", "Indica el objetivo del ahorro."),
    E("¿Cuántas proposiciones tiene «Cuando llegó el bus, Tomás se levantó, tomó su mochila y subió»?", "4", "Los verbos conjugados son llegó, levantó, tomó y subió.")],
   [E("Versión 1: «Hacía frío, por eso me puse la chaqueta.» Versión 2: «Me puse la chaqueta, por eso hacía frío.» ¿En cuál la relación causa-consecuencia es lógica?", "En la versión 1", "El frío es la causa y ponerse la chaqueta es la consecuencia; la versión 2 invierte el orden."),
    E("Una estudiante dice que en «Aunque estudió poco, aprobó» la palabra «aunque» indica causa. ¿Tiene razón?", "No", "Indica concesión: aprobó a pesar de estudiar poco.")],
   [E("Une en una sola oración con «porque»: «El río se desbordó. Llovió toda la semana.»", "El río se desbordó porque llovió toda la semana.", "La lluvia es la causa, así que va después de «porque»."),
    E("«Me duele la garganta, no iré al coro, mañana avisaré.» Tres proposiciones están separadas solo por comas, sin conector. ¿Cómo se llama esa unión?", "Yuxtaposición", "No hay conector; solo signos de puntuación.")]),
  [E("Un aviso del colegio dice: «Si llueve, la ceremonia será en el gimnasio; si hay sol, será en el patio.» Si mañana hay sol, ¿dónde será la ceremonia?", "En el patio", "Cada «si» marca una condición, y la condición que se cumple es la del sol.")],
  [E("¿Con qué se reconoce una proposición: con un verbo conjugado o con una coma?", "Con un verbo conjugado", "La coma solo separa; el verbo conjugado cuenta las proposiciones."),
   E("¿Qué conector sirve para marcar consecuencia: «así que» o «aunque»?", "Así que", "«Aunque» marca concesión."),
   E("En «Llegué, saludé, me senté», ¿las proposiciones están unidas por coordinación o por yuxtaposición?", "Yuxtaposición", "Solo hay comas, sin conector.")],
  ("Lee este texto de ejemplo: «El club de lectura se reunió el lunes, leyó dos capítulos y comentó los personajes. Aunque algunos estaban cansados, nadie se fue, porque querían saber el final.» 1) Cuenta las proposiciones de cada oración. 2) Marca los conectores y escribe la relación que cada uno crea. 3) Escribe una tercera oración compleja sobre el mismo club con un conector de finalidad.",
   "Primera oración: 3 proposiciones (se reunió, leyó, comentó), unidas por coma y por «y». Segunda: 3 proposiciones (estaban, se fue, querían): «aunque» marca concesión y «porque» marca causa. Tercera oración propia: «El club se reunirá otra vez para que todos terminen el libro.» («para que» marca finalidad).",
   ["cuenta bien las proposiciones", "identifica la relación de cada conector", "usa un conector de finalidad con sentido"], ["conteo anotado", "tres relaciones nombradas", "oración propia"], ["contar palabras en vez de verbos", "usar «aunque» como si fuera causa"], "Intercambia tu oración con otra persona: debe decir qué relación expresa tu conector y si está de acuerdo."),
  "Toma una noticia breve de un diario o de tu casa y marca los conectores de las dos primeras oraciones; escribe qué relación marca cada uno.",
  "Escribe una oración de cuatro proposiciones sobre tu tarde de ayer y rotula cada conector con su relación.")

L(OA17, 2,
  MAT,
  "Aprenderé a mantener claro a quién o a qué se refieren los pronombres de una oración compleja, para que nadie dude de qué se habla.",
  ["Reconozco las proposiciones de una oración compleja.", "Sé qué es un pronombre."],
  ["El referente es la persona, cosa o idea de la que se habla. En una oración compleja, pronombres como él, ella, lo, la, le o su toman el lugar de un nombre ya dicho (el antecedente). El lector debe poder saber cuál es ese antecedente sin adivinar.",
   "Hay ambigüedad cuando el pronombre puede apuntar a dos antecedentes posibles. En «Pablo le prestó el lápiz a Joaquín y él lo perdió», «él» puede ser Pablo o Joaquín. También ocurre con «su»: «Ana le dijo a Marta que su bicicleta estaba rota» no aclara de quién es la bicicleta. A veces el género ayuda: si uno es hombre y otro es mujer, «ella» solo apunta a la mujer.",
   "Para corregir, tienes cuatro caminos: repetir el nombre, cambiar el orden de la oración, usar discurso directo (con dos puntos y comillas) o agregar un dato que distinga. Pronombres como esto o eso pueden retomar una idea completa; úsalos solo si esa idea es la única posible."],
  [("antecedente", "palabra o idea ya nombrada a la que un pronombre se refiere"), ("ambigüedad", "cuando una expresión puede entenderse de dos maneras"), ("discurso directo", "cita de las palabras exactas de alguien, con dos puntos y comillas"), ("pronombre", "palabra que toma el lugar de un nombre")],
  [("Detectar ambigüedad", "En «Sara habló con Rita y ella aceptó el cambio», ¿se sabe quién aceptó?",
    ["Busco los antecedentes posibles de «ella»: Sara y Rita.", "Las dos son mujeres, así que el género no ayuda.", "No se sabe."],
    "No se sabe: puede ser Sara o Rita"),
   ("Corregir con discurso directo", "Corrige «Elisa le dijo a Pía que ella ganó» para que quede claro que ganó Pía.",
    ["El pronombre «ella» tiene dos candidatas.", "Uso discurso directo y la segunda persona.", "Escribo: Elisa le dijo a Pía: «Tú ganaste»."],
    "Elisa le dijo a Pía: «Tú ganaste».")],
  [("Creer que una coma elimina la ambigüedad.", "Se piensa que separar el pronombre cambia a quién apunta.", "La coma no cambia el antecedente: hay que nombrarlo, reordenar o citar."),
   ("Usar «esto» sin saber qué idea retoma.", "Hay varias ideas anteriores.", "Usa «esto» solo si apunta a una idea clara; si no, nombra la idea.")],
  ([E("En «Camila encontró una moneda y la guardó en el bolsillo», ¿a qué se refiere «la»?", "A la moneda", "Es el único objeto femenino nombrado antes."),
    E("En «Los alumnos entregaron sus informes», ¿a quiénes se refiere «sus»?", "A los alumnos", "El pronombre posesivo retoma al sujeto."),
    E("En «Pablo le prestó el lápiz a Joaquín y él lo perdió», ¿se sabe quién perdió el lápiz?", "No", "«Él» puede ser Pablo o Joaquín.")],
   [E("En «La profesora habló con la directora y ella aprobó el permiso», ¿cuántos referentes posibles tiene «ella»?", "2", "Puede ser la profesora o la directora."),
    E("«Rosa le contó a Elena que ella había ganado.» Versión 1: «Rosa le contó a Elena: “Gané”.» Versión 2: «Rosa le contó a Elena que había ganado.» ¿Cuál versión elimina la duda?", "La versión 1", "El discurso directo deja claro que habla Rosa; en la versión 2 sigue sin saberse quién ganó."),
    E("En «Hubo corte de luz toda la tarde. Esto impidió terminar la maqueta», ¿qué retoma «esto»?", "El corte de luz", "Es la idea anterior que explica el problema.")],
   [E("Corrige la ambigüedad repitiendo el nombre: «La profesora habló con la directora y ella aprobó el permiso» (aprobó la directora).", "La profesora habló con la directora y la directora aprobó el permiso.", "Repetir el nombre deja un único referente."),
    E("En «Ana le dijo a Marta que su bicicleta estaba rota», ¿se sabe de quién es la bicicleta?", "No", "«Su» puede apuntar a Ana o a Marta."),
    E("En «Le entregué el libro a Mateo y él lo leyó en una tarde», ¿a qué se refiere «lo»?", "Al libro", "Es el objeto masculino ya nombrado; «Mateo» es una persona y no encaja con «lo leyó».")],
   [E("«Conecté el cable A al router y el cable B al computador. Él estaba dañado.» Quien escribe quería decir que el cable A estaba dañado. ¿Qué reemplazo evita la confusión: «El cable A estaba dañado» o «Aquel estaba dañado»?", "El cable A estaba dañado", "Nombrar el cable deja un solo referente; «aquel» sigue siendo dudoso."),
    E("Una compañera dice que, si un pronombre tiene dos referentes posibles, basta con poner una coma antes de él. ¿Tiene razón?", "No", "La coma no cambia a qué apunta el pronombre; hay que nombrar, reordenar o citar.")],
   [E("Quien escribe quería decir que Ignacio debe llevar el balón. Corrige: «Nicolás le dijo a Ignacio que él debía llevar el balón». Usa discurso directo con «Tú».", "Nicolás le dijo a Ignacio: «Tú debes llevar el balón».", "Con discurso directo y «tú», solo Ignacio queda como responsable."),
    E("«El perro de Marcos persiguió al gato de Elisa. Él se subió a un árbol.» ¿Ayuda el género a saber quién se subió: sí o no?", "No", "Marcos, el perro y el gato son masculinos singulares, así que «él» puede apuntar a más de uno.")]),
  [E("Un afiche dice: «Entregue el formulario al secretario y a la tesorera. Ella lo revisará.» ¿Quién revisará el formulario?", "La tesorera", "«Ella» solo puede apuntar a la mujer; el género disipa la duda.")],
  [E("¿Cómo se llama la palabra ya nombrada a la que un pronombre apunta?", "Antecedente", "Es el referente anterior del pronombre."),
   E("¿Qué recurso sirve para aclarar: repetir el nombre o agregar una coma?", "Repetir el nombre", "La coma no cambia el referente."),
   E("¿El discurso directo usa dos puntos y comillas o puntos suspensivos?", "Dos puntos y comillas", "Así se muestran las palabras exactas de alguien.")],
  ("Lee este texto de ejemplo: «La capitana habló con la ingeniera y ella dijo que su equipo estaba listo. Luego le pidió que revisara el mapa.» 1) Subraya cada pronombre. 2) Escribe a quién podría apuntar cada uno. 3) Reescribe el texto para que quede claro que la ingeniera dijo que el equipo de la capitana estaba listo, y que la capitana pidió revisar el mapa a la ingeniera.",
   "Pronombres: ella, su, le (y «que revisara», sujeto tácito). «Ella» puede ser la capitana o la ingeniera; «su» puede ser de cualquiera; «le» puede ser la ingeniera o la capitana. Versión clara: «La capitana habló con la ingeniera. La ingeniera dijo: «Su equipo está listo». Entonces la capitana le pidió a la ingeniera que revisara el mapa».",
   ["encuentra todos los pronombres", "nombra los referentes posibles", "reescribe con un referente único cada vez"], ["pronombres subrayados", "versión corregida"], ["dejar «su» sin aclarar", "cambiar el sentido original"], "Lee tu versión a otra persona y pídele que diga a quién apunta cada pronombre; si dudó, ajústala."),
  "Observa un instructivo de tu casa (de un juguete o electrodoméstico) y busca un «lo» o «la» que podría confundir; di a qué cosa apunta.",
  "Escribe dos oraciones ambiguas sobre dos amigos y corrígelas con tres caminos distintos: repetir, reordenar y citar.")

L(OA17, 3,
  MAT,
  "Aprenderé a mantener los tiempos verbales ordenados en un texto para que el lector entienda qué ocurrió antes, qué ocurrió después y qué sigue ocurriendo.",
  ["Reconozco pasado, presente y futuro.", "Distingo el verbo conjugado de una oración."],
  ["La coherencia temporal es la correspondencia entre los tiempos verbales y el orden de los hechos. En un relato en pasado, los hechos principales van en pretérito simple (llegó, abrió) y las descripciones o acciones que duran van en pretérito imperfecto (hacía frío, llovía).",
   "Para marcar que algo ocurrió antes que otro hecho pasado, se usa el pretérito pluscuamperfecto (había salido). Así, «Cuando llegué, mi hermano ya había salido» deja claro que primero salió él. Para el futuro se usa el futuro simple (llegaré) o la forma «voy a + infinitivo». Los marcadores como ayer, mañana, antes o después deben coincidir con el tiempo del verbo.",
   "El error más común es cambiar de tiempo sin motivo: «Ayer fui al parque y luego como helado». Aquí «ayer» pide pasado; por eso lo correcto es «comí». Cambiar de tiempo es válido si hay una razón, por ejemplo pasar de narrar un hecho pasado a comentar una verdad general: «Perdí el bus porque salí tarde; siempre conviene salir con tiempo»."],
  [("coherencia temporal", "correspondencia entre los tiempos verbales y el orden de los hechos"), ("pretérito simple", "tiempo del pasado para hechos terminados, como «llegó»"), ("pretérito imperfecto", "tiempo del pasado para descripciones o acciones que duran, como «llovía»"), ("pluscuamperfecto", "tiempo para un hecho anterior a otro pasado, como «había salido»")],
  [("Corregir un salto de tiempo", "Corrige «Ayer fui al parque y luego como helado».",
    ["«Ayer» marca pasado.", "«Fui» está en pasado, pero «como» está en presente.", "Cambio «como» por «comí»."],
    "Ayer fui al parque y luego comí helado."),
   ("Marcar un hecho anterior", "Completa: «Cuando llegué al estadio, el partido ya ___ (empezar)».",
    ["El partido empezó antes de mi llegada.", "Necesito un tiempo para algo anterior a un pasado.", "Uso el pluscuamperfecto: había empezado."],
    "había empezado")],
  [("Mezclar presente y pasado en el mismo hecho.", "Se escribe como se habla, sin notar el cambio.", "Marca el tiempo del hecho y revisa que todos los verbos de esa secuencia coincidan."),
   ("Usar «ya» sin pluscuamperfecto cuando hay dos pasados.", "No se marca cuál hecho ocurrió primero.", "Usa «había + participio» para el hecho que ocurrió antes.")],
  ([E("Corrige: «Mañana viajé a Chillán». Escribe el verbo en futuro simple.", "Mañana viajaré a Chillán.", "«Mañana» pide futuro."),
    E("En «Anoche llovía y no pudimos salir», ¿«llovía» está en pretérito imperfecto o en pretérito simple?", "Pretérito imperfecto", "Describe una situación que duraba, no un hecho puntual."),
    E("¿Qué tiempo marca un hecho anterior a otro pasado: pluscuamperfecto o futuro?", "Pluscuamperfecto", "Ejemplo: «había salido».")],
   [E("«Cuando llegué, mi hermano ya había salido.» ¿Quién salió primero?", "El hermano", "El pluscuamperfecto «había salido» marca el hecho anterior."),
    E("En «Ayer compré pan y luego voy a casa», ¿qué verbo rompe la coherencia temporal?", "Voy", "«Ayer» pide pasado; «voy» está en presente."),
    E("«Hacía frío cuando salimos.» ¿Qué verbo es la descripción y cuál el hecho puntual?", "Hacía es la descripción; salimos es el hecho puntual", "El imperfecto describe el fondo y el simple cuenta lo que ocurrió.")],
   [E("Completa con el verbo en pretérito imperfecto: «Mientras Rodrigo ___ (leer), su hermana pintaba».", "leía", "Dos acciones que duran al mismo tiempo van en imperfecto."),
    E("Completa con pluscuamperfecto: «Cuando Elena llegó, la clase ya ___ (terminar)».", "había terminado", "La clase terminó antes de que ella llegara."),
    E("Corrige: «Mañana comimos en casa de mi abuela». Escribe la oración con el verbo en futuro con «ir a».", "Mañana vamos a comer en casa de mi abuela.", "Se cambia «comimos» por una forma de futuro con «ir a».")],
   [E("Un relato dice: «Salí del colegio, camino a casa, y de pronto veo un perro herido. Lo llevé al veterinario». ¿Qué verbo rompe el tiempo del relato y por qué?", "Veo, porque está en presente y el relato está en pasado", "Los demás verbos están en pasado: salí, llevé."),
    E("¿Es correcto cambiar de tiempo en «Perdí el bus porque salí tarde; siempre conviene salir con tiempo»?", "Sí", "El segundo verbo comenta una verdad general, por eso el cambio tiene una razón.")],
   [E("Según «Cuando llegamos, el cine ya había cerrado», ¿qué ocurrió primero: la llegada o el cierre?", "El cierre", "«Había cerrado» marca el hecho anterior a la llegada."),
    E("En «Llegó el bus. Ya había anochecido. Salimos corriendo», ¿qué hecho ocurrió antes de los otros dos?", "Anochecer", "El pluscuamperfecto «había anochecido» señala que ocurrió antes de la llegada del bus.")]),
  [E("Una bitácora dice: «Ayer plantamos lechugas. Hoy las regamos. Mañana las regamos de nuevo». ¿Cómo debe quedar el verbo de la última oración para coincidir con «mañana»?", "regaremos", "«Mañana» pide futuro, pero «regamos» está en presente.")],
  [E("¿Qué es la coherencia temporal: la correspondencia entre tiempos verbales y orden de los hechos, o la unión de palabras con coma?", "La correspondencia entre tiempos verbales y orden de los hechos", "No se trata de la puntuación sino de los tiempos."),
   E("¿Qué tiempo uso para describir un fondo en el pasado: imperfecto o pluscuamperfecto?", "Imperfecto", "Describe lo que duraba o estaba ocurriendo."),
   E("¿Un marcador como «mañana» exige verbo en pasado o en futuro?", "En futuro", "Los marcadores deben coincidir con el tiempo del verbo.")],
  ("Lee este texto de ejemplo y corrígelo: «El sábado fuimos a la playa. Hacía sol, pero el mar está frío. Cuando llegamos, mi primo ya había armado la carpa. Después jugamos fútbol y almorzamos. Al día siguiente volvemos a casa temprano». Marca los verbos que rompen la coherencia temporal y escribe la versión corregida.",
   "El texto mezcla tiempos: «está» debería ser «estaba» (descripción en pasado) y «volvemos» debería ser «volvimos» (el relato va en pasado). Versión corregida: «…Hacía sol, pero el mar estaba frío. Cuando llegamos, mi primo ya había armado la carpa… Al día siguiente volvimos a casa temprano».",
   ["identifica los verbos que rompen el orden", "iguala los tiempos del relato", "explica cada cambio"], ["lista de verbos corregidos", "versión final"], ["cambiar todos los verbos al mismo tiempo", "no explicar por qué cambió"], "Lee tu versión en voz alta; cada oración debe poder ubicarse en una línea de tiempo sin dudas."),
  "Anota hoy tres cosas que hiciste esta mañana, usando pretérito simple, y una que ya habías hecho antes, usando pluscuamperfecto.",
  "Escribe un relato de cuatro oraciones que incluya imperfecto, simple y pluscuamperfecto, y subraya cada tiempo con un color.")

L(OA17, 4,
  MAT,
  "Aprenderé a ubicar el sujeto de cada verbo, incluso cuando está lejos o no aparece escrito, para saber de quién se habla y cuidar la concordancia.",
  ["Reconozco verbo y sujeto en una oración simple.", "Sé qué es la concordancia de número."],
  ["El sujeto es de quién o de qué se dice algo y concuerda con el verbo en número y persona. Para encontrarlo, pregunta: ¿quién o qué + verbo? En «Los libros de la biblioteca llegaron temprano», ¿quiénes llegaron? Los libros de la biblioteca. Por eso el verbo va en plural.",
   "El sujeto puede estar tácito (omitido) cuando la terminación del verbo lo permite: «Llegamos tarde» tiene sujeto «nosotros». Pero en una oración compleja, un sujeto tácito debe poder recuperarse. En «Mateo habló con Julián y se fue», ¿quién se fue? La duda aparece porque hay dos sujetos posibles; conviene escribir «Mateo habló con Julián y luego Julián se fue».",
   "Cuando entre el sujeto y el verbo hay mucho texto, el error típico es concordar con la palabra más cercana. En «Las cajas de lápices que compró la escuela llegó ayer», el verbo «llegó» no concuerda con «las cajas». Lo correcto es «llegaron». Ubicar el sujeto antes de escribir el verbo evita ese error."],
  [("sujeto", "de quién o de qué se dice algo en la oración"), ("sujeto tácito", "sujeto no escrito, deducido por la terminación del verbo"), ("concordancia", "acuerdo de número y persona entre sujeto y verbo"), ("núcleo del sujeto", "palabra principal del sujeto, como «cajas» en «las cajas de lápices»")],
  [("Encontrar el sujeto distante", "En «Las ventanas del pasillo que pintaron en marzo quedaron limpias», ¿cuál es el sujeto?",
    ["Pregunto: ¿quiénes quedaron limpias?", "Las ventanas.", "El resto describe el sujeto: «del pasillo que pintaron en marzo»."],
    "Las ventanas del pasillo que pintaron en marzo"),
   ("Recuperar un sujeto tácito", "En «Inés habló con su prima y llegó tarde», ¿quién llegó tarde?",
    ["Veo dos sujetos posibles: Inés y su prima.", "La oración no lo aclara.", "Para evitar la duda, nombro al sujeto."],
    "No se sabe; hay que escribir «Inés ... y luego Inés llegó tarde» o «...su prima llegó tarde»")],
  [("Concordar con la palabra más cercana al verbo.", "Se olvida cuál es el núcleo del sujeto.", "Busca el núcleo del sujeto antes de elegir el verbo."),
   ("Dejar un sujeto tácito que se pueda confundir.", "El lector no sabe a quién se refiere el verbo.", "Nombra el sujeto cuando cambie o haya dos posibles.")],
  ([E("En «Los niños corren por el patio», ¿cuál es el sujeto?", "Los niños", "Responde a la pregunta ¿quiénes corren?"),
    E("En «Cantamos en el coro», ¿cuál es el sujeto tácito?", "Nosotros", "La terminación -amos indica primera persona del plural."),
    E("En «Mis primas viven en Temuco», ¿el verbo «viven» está en singular o en plural?", "En plural", "Concuerda con «mis primas», que es plural.")],
   [E("En «El conjunto de herramientas del taller llegó ayer», ¿cuál es el núcleo del sujeto?", "Conjunto", "El verbo «llegó» está en singular y concuerda con «conjunto»."),
    E("En «Pablo habló con Javier y se fue», ¿se sabe quién se fue?", "No", "Pablo y Javier son sujetos posibles."),
    E("En «Los cuadernos de la biblioteca que compró el colegio llegaron temprano», ¿cuál es el núcleo del sujeto?", "Cuadernos", "Es la palabra principal sobre la que se dice «llegaron».")],
   [E("Elige el verbo correcto: «Los frascos de pintura que trajo la profesora (alcanzó / alcanzaron) para todo el curso».", "alcanzaron", "El núcleo del sujeto es «frascos», en plural."),
    E("Completa con el verbo en plural: «Los estudiantes del curso que ganó el concurso ___ (recibir) un premio».", "recibieron", "El núcleo es «estudiantes»."),
    E("Escribe la oración con el sujeto aclarado: «Valentina saludó a Francisca y se sentó» (se sentó Francisca).", "Valentina saludó a Francisca y Francisca se sentó.", "Repetir el nombre deja claro quién se sentó.")],
   [E("En «Las profesoras del colegio dijeron que la feria fue un éxito», ¿qué verbo concuerda con el sujeto «Las profesoras del colegio»?", "Dijeron", "El núcleo «profesoras» está en plural y «colegio» solo lo completa."),
    E("Un compañero escribe «Las notas del curso fue buena». ¿Por qué hay error y cómo se corrige?", "El sujeto «las notas» es plural: «Las notas del curso fueron buenas»", "Concordar con «curso» y no con «notas» es el error clásico.")],
   [E("«Ayer el director, que conoce a todos los estudiantes, ___ (saludar) a cada curso.» ¿Cuál es el sujeto y qué verbo va?", "El director; saludó", "El sujeto es singular; lo que va entre comas lo complementa."),
    E("¿Cuántos sujetos distintos hay en «El perro ladró, la gata huyó y los pájaros se asustaron»?", "3", "Cada verbo tiene su propio sujeto: el perro, la gata y los pájaros.")]),
  [E("En un aviso: «Los vecinos del edificio que compraron plantas ___ (regar) el jardín cada lunes». ¿Qué verbo en plural va?", "riegan", "El sujeto es «los vecinos».")],
  [E("¿El sujeto tácito se deduce por la terminación del verbo o por una coma?", "Por la terminación del verbo", "La terminación indica persona y número."),
   E("¿Con qué debe concordar el verbo: con el núcleo del sujeto o con la palabra más cercana?", "Con el núcleo del sujeto", "Así se evita el error de concordancia."),
   E("¿Cuál pregunta ayuda a encontrar el sujeto: ¿quién o qué + verbo? o ¿cuándo + verbo?", "¿Quién o qué + verbo?", "Esa pregunta lleva al sujeto.")],
  ("Lee este párrafo de ejemplo: «Los libros del taller que compró la escuela llegó ayer. Camila habló con Daniela y salió corriendo. Las cajas de materiales que ordenó el profesor está en la bodega». 1) Subraya el sujeto de cada verbo. 2) Corrige los errores de concordancia. 3) Aclara el sujeto de la segunda oración.",
   "Corregido: «Los libros del taller que compró la escuela llegaron ayer. Camila habló con Daniela y Daniela salió corriendo (o Camila salió corriendo, según la intención). Las cajas de materiales que ordenó el profesor están en la bodega».",
   ["ubica el núcleo del sujeto", "corrige la concordancia", "aclara el sujeto dudoso"], ["sujetos subrayados", "párrafo corregido"], ["concordar con la palabra más cercana", "dejar el sujeto tácito ambiguo"], "Lee en voz alta cada verbo junto a su sujeto; debe sonar natural y no dejar dudas."),
  "Elige tres oraciones de un libro de tu casa y marca el sujeto de cada una.",
  "Escribe una oración con sujeto muy largo y otra con sujeto tácito, y explica cómo encontraste cada sujeto.")

L(OA17, 5,
  MAT,
  "Aprenderé a revisar un texto con oraciones complejas, usando una lista de comprobación de relaciones, referente, tiempos y sujeto.",
  ["Reconozco relaciones entre proposiciones.", "Sé ubicar el sujeto, el referente y el tiempo verbal."],
  ["Revisar es leer un texto con un propósito: encontrar lo que confunde y arreglarlo sin cambiar lo que se quiere decir. Para oraciones complejas conviene seguir cuatro pasos: 1) contar las proposiciones y mirar el conector; 2) comprobar que cada pronombre tenga un referente claro; 3) revisar los tiempos verbales; 4) ubicar el sujeto y comprobar la concordancia.",
   "Se revisa de una oración a la vez y se anota el problema con un nombre preciso: «conector equivocado», «pronombre ambiguo», «salto de tiempo» o «sujeto dudoso». Nombrar el problema ayuda a elegir la solución. Un conector equivocado se cambia; un pronombre ambiguo se reemplaza por el nombre; un salto de tiempo se corrige igualando los verbos; un sujeto dudoso se escribe de nuevo.",
   "Al terminar, lee el texto completo para comprobar que las correcciones no crearon un problema nuevo. Un buen texto revisado suena natural, se entiende a la primera lectura y conserva la idea original. Explicar cada decisión («cambié «aunque» por «porque» porque indica causa») es parte de revisar bien."],
  [("revisar", "leer un texto para encontrar y arreglar lo que confunde"), ("conector", "palabra que une proposiciones y marca una relación"), ("salto de tiempo", "cambio de tiempo verbal sin motivo"), ("lista de comprobación", "serie de preguntas que se aplican a cada oración")],
  [("Revisar una oración", "Revisa «Aunque se cayó, se lastimó la rodilla» pensando que quien escribió quería explicar una causa.",
    ["Cuento las proposiciones: dos.", "El conector «aunque» marca concesión, pero la idea es de causa-consecuencia.", "Cambio a «Como se cayó, se lastimó la rodilla» o «Se cayó y por eso se lastimó la rodilla»."],
    "Se cambia el conector por uno de causa: «Se cayó y por eso se lastimó la rodilla»"),
   ("Revisar un pronombre", "Revisa «Lucía le contó a Rosa que ella tenía fiebre» para que la enferma sea Rosa.",
    ["El pronombre «ella» puede apuntar a dos personas.", "Uso discurso directo con «tú».", "Escribo: Lucía le dijo a Rosa: «Tú tienes fiebre»."],
    "Lucía le dijo a Rosa: «Tú tienes fiebre».")],
  [("Corregir un problema pero crear otro.", "No se vuelve a leer el texto completo.", "Después de corregir, relee y repite la lista."),
   ("Cambiar el sentido original.", "Se reescribe sin comprobar la idea inicial.", "Antes de cambiar, anota qué quería decir quien escribió.")],
  ([E("¿Cuál es el primer paso de la lista: contar proposiciones y mirar el conector, o cambiar los verbos?", "Contar proposiciones y mirar el conector", "Es el paso 1 de la lista de comprobación."),
    E("¿Un pronombre ambiguo se corrige repitiendo el nombre o cambiando el color del texto?", "Repitiendo el nombre", "El nombre deja un solo referente."),
    E("¿Qué se corrige igualando verbos: un salto de tiempo o un conector?", "Un salto de tiempo", "Los verbos de una misma secuencia deben ir en el mismo tiempo.")],
   [E("«Estudié toda la noche, aunque aprobé la prueba.» Quien escribió quería decir que aprobó gracias a estudiar. ¿Qué conector es más adecuado: «por eso» o «aunque»?", "Por eso", "«Por eso» marca consecuencia; «aunque» marca obstáculo."),
    E("«Ayer fui al mercado y compro frutas.» ¿Qué problema tiene la oración?", "Salto de tiempo", "«Ayer» y «fui» están en pasado, pero «compro» está en presente."),
    E("«El director habló con el profesor y se fue.» ¿Qué problema tiene la oración?", "Sujeto dudoso", "«Se fue» puede ser el director o el profesor.")],
   [E("Corrige el salto de tiempo: «Ayer fui al mercado y compro frutas».", "Ayer fui al mercado y compré frutas.", "Los dos verbos quedan en pasado."),
    E("Corrige el sujeto dudoso: «El director habló con el profesor y se fue» (se fue el profesor).", "El director habló con el profesor y el profesor se fue.", "Nombrar al sujeto elimina la duda."),
    E("Corrige el conector equivocado: «No tenía hambre, así que comí un sándwich» si quiere decir que comió a pesar de no tener hambre. Escribe con «aunque».", "Aunque no tenía hambre, comí un sándwich.", "«Aunque» marca la concesión.")],
   [E("Una estudiante revisa: «Cuando llegó Tomás, la fiesta ya empezaba». Sugiere cambiar «empezaba» por «había empezado». ¿Es acertado el cambio?", "Sí", "Marca que la fiesta comenzó antes de su llegada."),
    E("Un compañero corrige «Vi a Ana y a su madre. Ella me saludó» cambiando «Ella» por «La madre de Ana». ¿Resuelve la ambigüedad?", "Sí", "Nombra un solo referente.")],
   [E("Anota cuántos problemas distintos tiene: «Ayer fui al parque con Julián y Pedro y se cayó. Llueve mucho, pero estuve mojado». Cuenta el sujeto dudoso, el salto de tiempo y el conector que no corresponde.", "3", "Hay un sujeto dudoso (¿quién se cayó?), un salto de tiempo (llueve) y un conector «pero» sin oposición."),
    E("Reescribe sin problemas: «Marta saludó a Sofía y se fue. Ayer fui y compro pan» si Marta se fue y el relato es del pasado.", "Marta saludó a Sofía y Marta se fue. Ayer fui y compré pan.", "Se aclara el sujeto y se iguala el tiempo.")]),
  [E("Un correo escolar dice: «El curso visitó el museo y compro entradas porque quería aprender». ¿Cuál es el principal problema temporal?", "El verbo «compro» está en presente", "El resto del texto está en pasado: visitó, quería.")],
  [E("¿La lista de comprobación sirve para encontrar problemas o para cambiar la idea del texto?", "Para encontrar problemas", "Revisar no cambia lo que se quiere decir."),
   E("¿Qué debes hacer al terminar de corregir: releer el texto completo o entregar sin leer?", "Releer el texto completo", "Así compruebas que la corrección no crea un problema nuevo."),
   E("¿Nombrar el problema ayuda a elegir la solución?", "Sí", "Cada problema tiene una corrección distinta.")],
  ("Revisa este texto de ejemplo con la lista de cuatro pasos: «El curso habló con el taller y presentó una obra en el salón. Aunque el público aplaudió mucho porque estaba entretenido. La directora habló con la profesora y ella dijo que su obra será la mejor. Todos estuvieron felices». Anota los problemas con su nombre y escribe la versión corregida.",
   "Problemas: oración incompleta («Aunque… porque…» sin proposición principal); pronombres ambiguos («ella», «su»); salto de tiempo («será»); sujeto dudoso en «presentó» (¿el curso o el taller?). Versión: «El curso habló con el taller y el curso presentó una obra en el salón. El público aplaudió mucho porque estaba entretenido. La directora habló con la profesora y la directora dijo que la obra del curso sería la mejor. Todos estuvieron felices».",
   ["nombra cada problema con precisión", "corrige sin cambiar la idea", "relee el texto final"], ["lista de problemas", "versión final"], ["corregir solo algunos problemas", "crear una ambigüedad nueva"], "Pide a otra persona que lea tu versión y diga si se entiende a la primera."),
  "Revisa una carta o mensaje tuyo con los cuatro pasos y anota qué cambiarías.",
  "Escribe un párrafo con cuatro errores a propósito y pide a alguien que los encuentre usando la lista.")
